mapper.select:
SELECT A.FINPROD_ID finprodId, A.FINPROD_MARKET_ID finprodMarketId, A.FINPROD_NAME finprodName, A.FINPROD_TYPE2 finprodType2, A.CCY ccy, A.VDATE vdate, A.MDATE mdate,
T2.CUSTOMER_NAME issuer,
A.CALENDAR_ID calendarId,
T1.CUSTOMER_NAME trusteeId,
T.CUSTOMER_NAME manager, A.ISSUE_AMT issueAmt, A.CAPI_INCOME_FEATURE capiIncomeFeature, B.TYPE_6 category, B.TYPE_7 type,
B.TYPE_9 type9, B.TYPE_10 type10, B.TYPE_11 type11, B.TYPE_12 type12,
FPR.RECOMMENDER recommender, MCP.COUNTER_NAME recommenderName,
D.INVESTMENT_ATTRIBUTES investmentAttributes FROM FIN_PRODUCT A
LEFT JOIN FIN_PRODUCT_RECOMMENT FPR ON FPR.FINPROD_ID = A.FINPROD_ID LEFT JOIN MST_COUNTER_PARTY MCP ON FPR.RECOMMENDER = MCP.COUNTER_ID
LEFT JOIN MST_CUSTOMER_INFO T ON T.CUSTOMER_ID = A.MANAGER
LEFT JOIN MST_CUSTOMER_INFO T1 ON T1.CUSTOMER_ID = A.ISSUER LEFT JOIN MST_CUSTOMER_INFO T2 ON T2.CUSTOMER_ID = A.TRUSTEE_ID,
FIN_PRODUCT_TYPE B, FIN_PRODUCT_ADD C, PA_FIN_PRODUCT D WHERE A.FINPROD_ID = B.FINPROD_ID AND A.FINPROD_ID = C.FINPROD_ID AND A.FINPROD_ID = D.FINPROD_ID
AND A.FINPROD_MARKET_ID LIKE CONCAT(CONCAT('%',#{finprodMarketId}),'%')
#{category,jdbcType=VARCHAR}
#{type,jdbcType=VARCHAR}
AND A.FINPROD_TYPE2 = #{FINPROD_TYPE_TG_F17, jdbcType = VARCHAR} AND A.PROFIT_TYPE = #{PROFIT_TYPE_03, jdbcType = VARCHAR}
AND A.VDATE >= DATE(#{startVDate})
AND A.VDATE >= DATE(#{endVDate})
AND A.MDATE >= DATE(#{startMDate})
AND A.MDATE >= DATE(#{endMDate})
AND A.MANAGER = #{manager,jdbcType=VARCHAR}
AND A.ISSUER = #{issuer,jdbcType=VARCHAR}
AND A.TRUSTEE_ID = #{trusteeId,jdbcType=VARCHAR}
#{type9,jdbcType=VARCHAR}
#{type10,jdbcType=VARCHAR}
#{type11,jdbcType=VARCHAR}
#{type12,jdbcType=VARCHAR}
